We start by proving the following auxiliary statement:

\begin{lemma}[Finding a Good Rectangle] \label{lem:good-rect}
Let $A \in \set{0, 1}^{X \times Y}$, let~\makebox{$\epsilon \in (0, 1)$} and $d \geq 1$, and assume that $\Ex[A] \geq 2^{-d}$. There is an algorithm $\RegRect(X, Y, A, \epsilon, d)$ computing~\makebox{$X^* \subseteq X, Y^* \subseteq Y$} such that:
\begin{enumerate}
    \item Let $A^* = A[X^*, Y^*]$. Then $A^*$ is $(\epsilon, 2, d)$-regular and $\epsilon$-min-degree.
    \item $\Ex[A^*] \geq \Ex[A]$.
    \item $|X^*| \, |Y^*| \geq \exp(-d^3 \poly(\epsilon^{-1})) \cdot |X| \, |Y|$.
\end{enumerate}
The algorithm is deterministic and runs in time $n^2 \cdot \exp(d^3 \poly(\epsilon^{-1}))$ (where $n = |X| + |Y|$).
\end{lemma}
\begin{proof}
We start with the description of the algorithm; see \cref{alg:reg-rect} for the pseudocode. We first apply \cref{lem:min-degree} to compute~\makebox{$X' \subseteq X$} and $A' \gets A[X', Y]$ (with parameters $\epsilon$ and $\gamma \gets \frac12$, \cref{alg:reg-rect:line:min-degree}). The lemma guarantees one of two cases: Either~$A'$ is $\epsilon$-min-degree, or $\Ex[A'] \geq (1 + \frac{\epsilon}{2}) \Ex[A]$. In the latter case we recurse on the subinstance~$(X', Y, A')$ to find a good rectangle (\cref{alg:reg-rect:line:min-degree-dense,alg:reg-rect:line:min-degree-recur}). In the former case we continue and apply \cref{thm:sifting} to $(X', Y, A')$ (with parameters $\epsilon$ and $d$). If the theorem returns a rectangle~\makebox{$X'' \times Y'' \subseteq X' \times Y$} with~\makebox{$\Ex[A[X'', Y'']] \geq (1 + \frac{\epsilon}{2}) \Ex[A]$}, then we recurse on the subinstance $(X'', Y'', A[X'', Y''])$ (\cref{alg:reg-rect:line:sifting,alg:reg-rect:line:sifting-recur}). Otherwise, \cref{thm:sifting} guarantees that $A'$ is $(\epsilon, 2, d)$-regular. In this case we finally return $X^* \gets X', Y^* \gets Y$ (\cref{alg:reg-rect:line:return}).


\begin{algorithm}[t]
\caption{Implements the algorithm from \cref{lem:good-rect}.} \label{alg:reg-rect}
\begin{algorithmic}[1]
    \Procedure{\RegRect}{$X, Y, A, \epsilon, d$}
        \State Compute $X' \gets \MinDegree(X, Y, A, \epsilon, \frac{1}{2})$ and $A' \gets A[X', Y]$ \label{alg:reg-rect:line:min-degree}
        \If{$\Ex[A'] \geq (1 + \frac{\epsilon}{2}) \Ex[A]$} \label{alg:reg-rect:line:min-degree-dense}
            \State\Return $\RegRect(X', Y, A', \epsilon, d)$ \label{alg:reg-rect:line:min-degree-recur}
        \EndIf
        \If{$\Sift(X', Y, A', \epsilon, d)$ returns a denser rectangle $X'' \times Y'' \subseteq X' \times Y$} \label{alg:reg-rect:line:sifting}
            \State\Return $\RegRect(X'', Y'', A[X'', Y''], \epsilon, d)$ \label{alg:reg-rect:line:sifting-recur}
        \EndIf
        \State\Return $X', Y$ \label{alg:reg-rect:line:return}
    \EndProcedure
\end{algorithmic}
\end{algorithm}

The correctness of Property~1 is clear: We either recurse, or return the submatrix $A'$ that is $\epsilon$-min-degree and $(\epsilon, 2, d)$-regular. Moreover, it is easy to prove that Property~2 holds: \cref{lem:min-degree} states that $\Ex[A'] \geq \Ex[A]$ in either case; and if the algorithm recurses, then the density even strictly increases. It remains to prove Property~3 and to analyze the running time of this algorithm.

\paragraph{Correctness of Property~3}
First assume that the algorithm does not recurse and returns~$X', Y$. In this case, \cref{lem:min-degree} guarantees that $|X'| \geq \frac{1}{2} \cdot |X|$, and thus $|X^*| \, |Y^*| \geq \frac12 \cdot |X| \, |Y|$. Next, consider the recursive cases. By \cref{lem:min-degree,thm:sifting}, in both cases we recurse on a rectangle of size at least $\min\set{\frac{1}{2}, \frac{\epsilon}{16} \cdot \Ex[A]^{2d}} \cdot |X| \, |Y| = \frac{\epsilon}{16} \cdot \Ex[A]^{2d} \cdot |X| \, |Y|$ and with density at least~\makebox{$(1 + \frac{\epsilon}{2}) \Ex[A]$}. It follows by induction that the algorithm returns a rectangle of size
\begin{equation*}
    |X^*| \, |Y^*| \geq \tfrac{1}{2} \cdot \parens*{\tfrac{\epsilon}{16} \cdot \Ex[A]^{2d}}^{\log_{1+\frac{\epsilon}{2}}(\Ex[A]^{-1})} \cdot |X| \, |Y| \geq \exp(-d^3 \poly(\epsilon^{-1})) \cdot |X| \, |Y|,
\end{equation*}
where in the latter bound we used that $\log(1 + \epsilon) \geq \epsilon$ for all $\epsilon \in (0, 1)$, and that initially $\Ex[A] \geq 2^{-d}$.

\paragraph{Running Time}
The algorithm reaches recursion depth at most \smash{$\log_{1+\frac{\epsilon}{2}}(\Ex[A]^{-1}) = \Order(d / \epsilon)$}, which causes a negligible overhead in the running time. The call to $\MinDegree$ (\cref{lem:min-degree}) takes time~$\Order(n^2)$, and the call to $\Sift$ (\cref{thm:sifting}) takes time $n^2 \cdot (\epsilon\Ex[A])^{-\Order(d^2)} = n^2 \cdot \exp(d^3 \poly(\epsilon^{-1}))$. All in all, the running time is $n^2 \cdot \exp(d^3 \poly(\epsilon^{-1}))$ as claimed.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
We start with the description of the algorithm; see \cref{alg:edge-decomposition} for the pseudocode. As a first step, we compute the density~$\Ex[A]$ and test whether $\Ex[A] \leq 2^{-d}$. In this case we can immediately stop and return the trivial decomposition~$\set{(X, Y, A)}$ (\cref{alg:edge-decomposition:line:sparse,alg:edge-decomposition:line:sparse-return}). Otherwise, we can apply \cref{lem:good-rect} to compute a good rectangle~\makebox{$X^* \times Y^* \subseteq X \times Y$}. We then take $(X^*, Y^*, A[X^*, Y^*])$ as one piece of the decomposition, and recurse on the remaining graph where we remove all edges in~\makebox{$X^* \times Y^*$} (\cref{alg:edge-decomposition:line:reg-rect,alg:edge-decomposition:line:recur}; in the pseudocode by slight abuse of notation we denote the remaining graph by $A - A[X^*, Y^*]$).

\begin{algorithm}[t]
\caption{Implements the algorithm from \cref{thm:edge-decomposition}.} \label{alg:edge-decomposition}
\begin{algorithmic}[1]
    \Procedure{\ADecomposition}{$X, Y, A, \epsilon, d$}
        \If{$\Ex[A] \leq 2^{-d}$} \label{alg:edge-decomposition:line:sparse}
            \State\Return $\set{(X, Y, A)}$ \label{alg:edge-decomposition:line:sparse-return}
        \EndIf
        \State Compute $X^*, Y^* \gets \RegRect(X, Y, A, \epsilon, d)$ \label{alg:edge-decomposition:line:reg-rect}
        \State\Return $\set{(X^*, Y^*, A[X^*, Y^*])} \cup \ADecomposition(X, Y, A - A[X^*, Y^*], \epsilon, d)$ \label{alg:edge-decomposition:line:recur}
    \EndProcedure
\end{algorithmic}
\end{algorithm}

It is easy to see that Property~1 holds: We either cover $A$ entirely in the base case, or we cover some part $X^* \times Y^*$ and remove that part in the recursive call. Moreover, Property~2 easily follows from the guarantee of \cref{lem:good-rect}. It remains to prove Properties~3 and 4, and to analyze the running time.

\paragraph{Correctness of Property~3}
For a collection of tuples $\mathcal S$ as returned by the algorithm, let us define
\begin{equation*}
    C(\mathcal S) = \sum_{(X', Y', A') \in \mathcal S} |X'| \, |Y'|.
\end{equation*}
Our goal is to prove that $C(\mathcal S) \leq (d + 2) \cdot |X| \, |Y|$, for any input $(X, Y, A)$, where $\mathcal S$ is the set returned by the algorithm. This is clear whenever $\Ex[A] \leq 2^{-d}$ (as then the algorithm returns the trivial partition $\set{(X, Y, A)}$). By induction we prove that whenever $\Ex[A] \geq 2^{-d}$ then
\begin{equation*}
    C(\mathcal S) \leq (d + 2 - \log(\Ex[A]^{-1})) \cdot |X| \, |Y|.
\end{equation*}
Let $\mathcal S^*$ denote the output of the recursive call $\ADecomposition(X, Y, A - A[X^*, Y^*], \epsilon, d)$, and let $\delta^*$ denote the density of $A - A[X^*, Y^*]$. Clearly, $C(\mathcal S) = |X^*| \, |Y^*| + C(\mathcal S^*)$. If $\delta^* \leq 2^{-d}$, then $C(\mathcal S^*) \leq |X| \, |Y|$ and thus $C(\mathcal S) \leq 2 |X| \, |Y|$ as claimed. Otherwise, recall that \cref{lem:good-rect} guarantees that the density of the rectangle $X^* \times Y^*$ does not decrease, $\Ex[A[X^*, Y^*]] \geq \Ex[A]$. It follows that \smash{$\delta^* \geq \Ex[A] - \Ex[A] \cdot \frac{|X^*| \, |Y^*|}{|X| \, |Y|}$}, and thus by induction:
\begin{align*}
    C(\mathcal S) &= |X^*| \, |Y^*| + C(\mathcal S^*) \\
    &\leq |X^*| \, |Y^*| + (d + 2 - \log((\delta^*)^{-1}) \cdot |X| \, |Y| \\
    &\leq |X^*| \, |Y^*| + (d + 2 - \log(\Ex[A]^{-1}) - \log((1 - \tfrac{|X^*| \, |Y^*|}{|X| \, |Y|})^{-1})) \cdot |X| \, |Y| \\
    &\leq |X^*| \, |Y^*| + (d + 2 - \log(\Ex[A]^{-1}) - \tfrac{|X^*| \, |Y^*|}{|X| \, |Y|}) \cdot |X| \, |Y| \\
    &= (d + 2 - \log(\Ex[A]^{-1})) \cdot |X| \, |Y|.
\end{align*}

\paragraph{Correctness of Property~4}
Note that $L$ is the recursion depth of the algorithm. To prove that~$L$ is bounded as claimed, we argue that with every recursive call the density of the matrix decreases. Specifically, each output $X^*, Y^*$ has size at least $|X^*| \, |Y^*| \geq \exp(-d^3 \poly(\epsilon^{-1})) \cdot |X| \cdot |Y|$ by \cref{lem:good-rect}, and the density of the submatrix $A^* = A[X^*, Y^*]$ satisfies~\smash{$\Ex[A^*] \geq \Ex[A] \geq 2^{-d}$} (as otherwise, if $\Ex[A] \leq 2^{-d}$, the algorithm had terminated already). Thus, each recursive call reduces the density of the graph by~\smash{$\Ex[A^*] \cdot \frac{|X^*| \, |Y^*|}{|X| \, |Y|} \geq 2^{-d} \cdot \exp(-d^3 \poly(\epsilon^{-1})) = \exp(-d^3 \poly(\epsilon^{-1}))$}, and the algorithm necessarily terminates after $L \leq \exp(d^3 \poly(\epsilon^{-1}))$ recursive calls.

\paragraph{Running Time}
We have already bounded the recursion depth in the previous paragraph, so focus on a single execution. The dominant cost is the call to $\RegRect$ (\cref{lem:good-rect}) which takes time $n^2 \cdot \exp(d^3 \poly(\epsilon^{-1}))$. The total time is $L \cdot n^2 \cdot \exp(d^3 \poly(\epsilon^{-1})) = n^2 \cdot \exp(d^3 \poly(\epsilon^{-1}))$.
\end{proof}
